        recommendedParts: { description: "The CJCB requires meticulous preventative maintenance. Protect the CP4 pump with a bypass kit, and monitor the DPF closely.", parts: [ { category: "Timing Belt Kit", brand: "Continental", note: "The CT1139K1 kit comprehensively includes the belt, tensioner, and rollers required for the 210k km service." }, { category: "Water Pump", brand: "HEPU", note: "Always replace the water pump when doing the timing belt. Use a metal impeller version." }, { category: "CP4 Bypass Kit", brand: "Whitbread / S&S", note: "Saves the fuel injectors and lines if the high-pressure fuel pump grenades itself." }, { category: "Oil Pump Hex Shaft Upgrade", brand: "KMB Parts", note: "Even if your car has the 100mm shaft, upgrading to a hardened version provides peace of mind against oil starvation." }, { category: "Fuel Filter", brand: "Mahle", note: "Replace every 30,000 km. The CP4 pump is incredibly sensitive to poor fuel quality and water contamination." }, { category: "DPF Pressure Sensor", brand: "Bosch", note: "Fails frequently, causing the DPF to stop regenerating and clog solid." }, { category: "EGR Valve", brand: "Pierburg", note: "Clogs with carbon soot over time. Replacing it restores smooth idling and fuel economy." }, { category: "Glow Plugs", brand: "Beru", note: "Some cylinders may use expensive pressure-sensing glow plugs. Verify via VIN." }, { category: "Oil Filter", brand: "Mann-Filter", note: "High quality cartridge filter. Essential for the 507.00 long-life oil intervals." }, { category: "Dual Mass Flywheel (DMF)", brand: "LuK", note: "Replaces the clunking, vibrating factory unit to restore smooth power delivery." } ] },
        maintenanceSchedule: { fluidsAndDrivetrain: [ { interval: "2 Years", timeLimit: "2 years", task: "Brake Fluid Flush", details: "Hydroscopic brake fluid aggressively absorbs water. Flushing it prevents ABS pump corrosion and dangerous brake fade.", parts: ["1.0L DOT 4"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "60 - 100" }, { interval: "60,000 km", timeLimit: "5 years", task: "Automatic Transmission Fluid (If 0AW CVT)", details: "Dropping the fluid in the Multitronic CVT is absolutely critical. Failure to do this guarantees rapid gearbox destruction.", parts: ["CVT Fluid", "Filter Kit"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "200 - 350" }, { interval: "80,000 km", timeLimit: "8 years", task: "Manual Transmission Fluid", details: "Changing the manual gearbox oil improves cold-shifting smoothness and drastically extends synchronizer life.", parts: ["3.2L 75W-90 GL-4"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "80 - 120" }, { interval: "100,000 km", timeLimit: "5 years", task: "Coolant Flush (G12++)", details: "Flushing the entire cooling system protects the iron block and aluminum head from internal rust.", parts: ["G12++ Coolant Mix"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "60 - 100" } ], oilAndFilters: [ { interval: "15,000 km", timeLimit: "1 year", task: "Engine Oil & Filter", details: "CRITICAL. Do not use the 30k km factory interval. Frequent changes with 507.00 oil protect the turbo and balance shaft bearings.", parts: ["Filter", "5.0L 507.00 Oil"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "70 - 100" }, { interval: "30,000 km", timeLimit: "2 years", task: "Cabin Air Filter", details: "Prevents dust and allergens from entering the cabin.", parts: ["Cabin Filter"], importance: "Low", laborDifficulty: "Easy", estimatedCost: "15 - 30" }, { interval: "30,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "A clogged air filter heavily restricts the turbocharger's breathing, causing black smoke and rapid DPF clogging.", parts: ["Engine Air Filter"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "20 - 35" }, { interval: "30,000 km", timeLimit: "2 years", task: "Fuel Filter", details: "CRITICAL. The CP4 pump relies entirely on diesel for lubrication. Replace the filter frequently to prevent water ingestion and pump failure.", parts: ["Inline Fuel Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "25 - 45" } ], ignitionAndEngine: [ { interval: "150,000 km", timeLimit: "N/A", task: "Hex Shaft Check (Oil Pump)", details: "Drop the oil pan to inspect the hex key in the balance shaft module. If showing wear, upgrade to a hardened version.", parts: ["Hex Shaft Kit", "Sealant"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "300 - 600" }, { interval: "210,000 km", timeLimit: "5 years", task: "Timing Belt & Water Pump Kit", details: "CRITICAL. Do not exceed the time limit even if mileage is low. Snapping the belt totals the cylinder head.", parts: ["Timing Kit", "Pump"], importance: "Critical", laborDifficulty: "Advanced", estimatedCost: "450 - 650" } ], preventiveAndSuspension: [ { interval: "60,000 km", timeLimit: "N/A", task: "Front Multi-Link Suspension Arms", details: "The incredibly heavy iron TDI block entirely destroys the complex B8 front control arms, causing severe clunking over bumps.", parts: ["Control Arm Kit"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "400 - 800" }, { interval: "80,000 km", timeLimit: "N/A", task: "DPF Ash Level Check", details: "Use VCDS to check the ash mass in the DPF. If it is nearing capacity, the DPF must be professionally cleaned or removed.", parts: ["None"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "Free (VCDS)" } ], coolingAndHvac: [ { interval: "100,000 km", timeLimit: "8 years", task: "Coolant Expansion Tank", details: "The plastic tank turns yellow and cracks from heat pressure, causing sudden coolant loss.", parts: ["Expansion Tank", "Cap"], importance: "Medium", laborDifficulty: "Easy", estimatedCost: "30 - 50" } ], engineMechanical: [ { interval: "100,000 km", timeLimit: "N/A", task: "Intake Manifold & EGR Cleaning", details: "Physically remove the intake manifold and burn/scrape out the massive accumulation of hardened soot and oil sludge.", parts: ["Intake Gasket Sets"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "150 - 250" } ] },
