        fluidCapacities: [ { system: "Engine Oil (Service Fill)", capacity: "5.0 Liters", spec: "VW 507.00 (5W-30 Fully Synthetic)" }, { system: "Coolant (Total System)", capacity: "8.0 Liters", spec: "G12++ (Pink/Violet)" }, { system: "Manual Transmission (6-Speed)", capacity: "3.2 Liters", spec: "G 052 911 A2 (Fully Synthetic 75W-90 GL-4)" }, { system: "Automatic Trans (0AW CVT)", capacity: "7.0L Total / 6.0L Service", spec: "G 052 516 A2 (CVT Fluid)" }, { system: "Brake Fluid", capacity: "1.0 Liter (Flush)", spec: "DOT 4" }, { system: "Power Steering", capacity: "Electromechanical", spec: "N/A" }, { system: "A/C Refrigerant", capacity: "600g ± 20g", spec: "R134a" }, { system: "Fuel Tank", capacity: "65 Liters", spec: "Standard Diesel" } ],
